SELECT intahun, chketteam, Market_Nielsen, KP, SUM(Podes) AS Podes,
    MAX(EC_1) AS EC_1, MAX(AT_1) AS AT_1, SUM(QTY_1) AS QTY_1, SUM(RP_1) AS RP_1, SUM(KG_1) AS KG_1,
    MAX(EC_2) AS EC_2, MAX(AT_2) AS AT_2, SUM(QTY_2) AS QTY_2, SUM(RP_2) AS RP_2, SUM(KG_2) AS KG_2,
    MAX(EC_3) AS EC_3, MAX(AT_3) AS AT_3, SUM(QTY_3) AS QTY_3, SUM(RP_3) AS RP_3, SUM(KG_3) AS KG_3,
    MAX(EC_4) AS EC_4, MAX(AT_4) AS AT_4, SUM(QTY_4) AS QTY_4, SUM(RP_4) AS RP_4, SUM(KG_4) AS KG_4,
    MAX(EC_5) AS EC_5, MAX(AT_5) AS AT_5, SUM(QTY_5) AS QTY_5, SUM(RP_5) AS RP_5, SUM(KG_5) AS KG_5,
    MAX(EC_6) AS EC_6, MAX(AT_6) AS AT_6, SUM(QTY_6) AS QTY_6, SUM(RP_6) AS RP_6, SUM(KG_6) AS KG_6,
    MAX(EC_7) AS EC_7, MAX(AT_7) AS AT_7, SUM(QTY_7) AS QTY_7, SUM(RP_7) AS RP_7, SUM(KG_7) AS KG_7,
