    MAX(EC_11) AS EC_11, MAX(AT_11) AS AT_11, SUM(QTY_11) AS QTY_11, SUM(RP_11) AS RP_11, SUM(KG_11) AS KG_11,
    MAX(EC_12) AS EC_12, MAX(AT_12) AS AT_12, SUM(QTY_12) AS QTY_12, SUM(RP_12) AS RP_12, SUM(KG_12) AS KG_12
