        WHEN KP = 'PENGURANG BLASTOZ' THEN 'BLASTOZ REG'
        WHEN KP = 'PENGURANG BLASTOZ + FULLO BLASTO' THEN 'BLASTOZ + FULLO BLASTO REG'
        WHEN KP = 'PENGURANG IMPERIAL CREME' THEN 'IMPERIAL CREME REG'
        WHEN KP = 'PENGURANG FULLO' THEN 'FULLO REG'
        WHEN KP = 'PENGURANG CANDY' THEN 'CANDY REG'
        WHEN KP = 'PENGURANG BLASTER' THEN 'BLASTER REG'
        WHEN KP = 'PENGURANG MINT Z' THEN 'MINT Z REG'
        WHEN KP = 'PENGURANG TANGO WAFER 2000UP' THEN 'TANGO WAFER 2000UP'
        WHEN KP = 'PENGURANG TANGO WAFER CHOCOLATE 7000' THEN 'TANGO WAFER CHOCOLATE 7000'
        WHEN KP = 'PENGURANG TANGO WAFER CHOCOLATE 2000UP' THEN 'TANGO WAFER CHOCOLATE 2000UP'
