        WHEN KP = 'PENGURANG TANGO 2000UP' THEN 'TANGO 2000UP'
        WHEN KP = 'PENGURANG TANGO CHOCOLATE 7000' THEN 'TANGO CHOCOLATE 7000'
        WHEN KP = 'PENGURANG TANGO CHOCOLATE 2000UP' THEN 'TANGO CHOCOLATE 2000UP'
