            'PENGURANG TANGO VANILLA 2000UP', 'PENGURANG TANGO OTHERS 7000', 'PENGURANG CHIZMILL' , 'PENGURANG BLASTOZ + FULLO BLASTO', 'PENGURANG TANGO WALUT') THEN -1*RP_12 ELSE RP_12 END AS RP_12,
        CASE WHEN KP IN ('PENGURANG TANGO WAFER', 'PENGURANG TANGO WAFFLE', 'PENGURANG BLASTOZ', 'PENGURANG BLASTOZ + FULLO BLASTO',                               'PENGURANG IMPERIAL CREME', 'PENGURANG FULLO', 
            'PENGURANG CANDY', 'PENGURANG BLASTER', 'PENGURANG MINT Z', 'PENGURANG TANGO WAFER 2000UP', 'PENGURANG TANGO WAFER CHOCOLATE 7000',
            'PENGURANG TANGO WAFER CHOCOLATE 2000UP', 'PENGURANG TANGO WAFER VANILLA 7000', 'PENGURANG TANGO WAFER VANILLA 2000UP',
            'PENGURANG TANGO WAFER CHOCO SERIES 7000', 'PENGURANG TOTAL TANGO', 'PENGURANG TANGO', 'PENGURANG TOTAL TANGO 2000UP',
            'PENGURANG TANGO CHOCOLATE 7000', 'PENGURANG TANGO CHOCOLATE 2000UP', 'PENGURANG TANGO VANILLA 7000',
            'PENGURANG TANGO VANILLA 2000UP', 'PENGURANG TANGO OTHERS 7000', 'PENGURANG CHIZMILL' , 'PENGURANG BLASTOZ + FULLO BLASTO', 'PENGURANG TANGO WALUT') THEN -1*KG_12 ELSE KG_12 END AS KG_12    
    FROM (SELECT intahun-2000 AS intahun, 
	        chketteam, Market_Nielsen, KP, SUM(Podes) AS Podes,
	        SUM(EC_1*Podes)/SUM(Podes) AS EC_1, SUM(AT_1) AS AT_1, SUM(QTY_1) AS QTY_1, SUM(RP_1) AS RP_1, SUM(Kg_1) AS KG_1,
	        SUM(EC_2*Podes)/SUM(Podes) AS EC_2, SUM(AT_2) AS AT_2, SUM(QTY_2) AS QTY_2, SUM(RP_2) AS RP_2, SUM(Kg_2) AS KG_2,
	        SUM(EC_3*Podes)/SUM(Podes) AS EC_3, SUM(AT_3) AS AT_3, SUM(QTY_3) AS QTY_3, SUM(RP_3) AS RP_3, SUM(Kg_3) AS KG_3,
	        SUM(EC_4*Podes)/SUM(Podes) AS EC_4, SUM(AT_4) AS AT_4, SUM(QTY_4) AS QTY_4, SUM(RP_4) AS RP_4, SUM(Kg_4) AS KG_4,
	        SUM(EC_5*Podes)/SUM(Podes) AS EC_5, SUM(AT_5) AS AT_5, SUM(QTY_5) AS QTY_5, SUM(RP_5) AS RP_5, SUM(Kg_5) AS KG_5,
	        SUM(EC_6*Podes)/SUM(Podes) AS EC_6, SUM(AT_6) AS AT_6, SUM(QTY_6) AS QTY_6, SUM(RP_6) AS RP_6, SUM(Kg_6) AS KG_6,
	        SUM(EC_7*Podes)/SUM(Podes) AS EC_7, SUM(AT_7) AS AT_7, SUM(QTY_7) AS QTY_7, SUM(RP_7) AS RP_7, SUM(Kg_7) AS KG_7,
	        SUM(EC_8*Podes)/SUM(Podes) AS EC_8, SUM(AT_8) AS AT_8, SUM(QTY_8) AS QTY_8, SUM(RP_8) AS RP_8, SUM(Kg_8) AS KG_8,
	        SUM(EC_9*Podes)/SUM(Podes) AS EC_9, SUM(AT_9) AS AT_9, SUM(QTY_9) AS QTY_9, SUM(RP_9) AS RP_9, SUM(Kg_9) AS KG_9,
	        SUM(EC_10*Podes)/SUM(Podes) AS EC_10, SUM(AT_10) AS AT_10, SUM(QTY_10) AS QTY_10, SUM(RP_10) AS RP_10, SUM(Kg_10) AS KG_10,
	        SUM(EC_11*Podes)/SUM(Podes) AS EC_11, SUM(AT_11) AS AT_11, SUM(QTY_11) AS QTY_11, SUM(RP_11) AS RP_11, SUM(Kg_11) AS KG_11,
	        SUM(EC_12*Podes)/SUM(Podes) AS EC_12, SUM(AT_12) AS AT_12, SUM(QTY_12) AS QTY_12, SUM(RP_12) AS RP_12, SUM(Kg_12) AS KG_12
	      FROM( SELECT intahun, chtipemarket, chtipelokasi, chketlokasi, chketteam, KP,     
	            MAX(deEC_M1) AS EC_1, MAX(inAT_M1) AS AT_1, SUM(deQTY_M1) AS QTY_1, SUM(deRP_M1) AS RP_1, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M1 END) AS Kg_1,
	            MAX(deEC_M2) AS EC_2, MAX(inAT_M2) AS AT_2, SUM(deQTY_M2) AS QTY_2, SUM(deRP_M2) AS RP_2, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M2 END) AS Kg_2,
	            MAX(deEC_M3) AS EC_3, MAX(inAT_M3) AS AT_3, SUM(deQTY_M3) AS QTY_3, SUM(deRP_M3) AS RP_3, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M3 END) AS Kg_3,
	            MAX(deEC_M4) AS EC_4, MAX(inAT_M4) AS AT_4, SUM(deQTY_M4) AS QTY_4, SUM(deRP_M4) AS RP_4, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M4 END) AS Kg_4,
	            MAX(deEC_M5) AS EC_5, MAX(inAT_M5) AS AT_5, SUM(deQTY_M5) AS QTY_5, SUM(deRP_M5) AS RP_5, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M5 END) AS Kg_5,
	            MAX(deEC_M6) AS EC_6, MAX(inAT_M6) AS AT_6, SUM(deQTY_M6) AS QTY_6, SUM(deRP_M6) AS RP_6, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M6 END) AS Kg_6,
	            MAX(deEC_M7) AS EC_7, MAX(inAT_M7) AS AT_7, SUM(deQTY_M7) AS QTY_7, SUM(deRP_M7) AS RP_7, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M7 END) AS Kg_7,
	            MAX(deEC_M8) AS EC_8, MAX(inAT_M8) AS AT_8, SUM(deQTY_M8) AS QTY_8, SUM(deRP_M8) AS RP_8, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M8 END) AS Kg_8,
	            MAX(deEC_M9) AS EC_9, MAX(inAT_M9) AS AT_9, SUM(deQTY_M9) AS QTY_9, SUM(deRP_M9) AS RP_9, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M9 END) AS Kg_9,
	            MAX(deEC_M10) AS EC_10, MAX(inAT_M10) AS AT_10, SUM(deQTY_M10) AS QTY_10, SUM(deRP_M10) AS RP_10, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M10 END) AS Kg_10,
	            MAX(deEC_M11) AS EC_11, MAX(inAT_M11) AS AT_11, SUM(deQTY_M11) AS QTY_11, SUM(deRP_M11) AS RP_11, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M11 END) AS Kg_11,
	            MAX(deEC_M12) AS EC_12, MAX(inAT_M12) AS AT_12, SUM(deQTY_M12) AS QTY_12, SUM(deRP_M12) AS RP_12, SUM(CASE WHEN Konversi IS NULL THEN 0 ELSE Konversi*deQTY_M12 END) AS Kg_12
        		FROM DtDWHBI.RPT_EAO_Monthly AS a
        		INNER JOIN DtCMOBI.Ketentuan_AllItemGC AS c
                		ON a.chketproduk = c.chketproduk
		        LEFT JOIN DtCMOBI.CK_Konfigurasi_Item AS k
		               ON a.chkdproduk = k.kode
		        WHERE chketteam IN ('Total', '27-TEAM A11', '28-TEAM AEB')
		        GROUP BY intahun, chtipemarket, chtipelokasi, chketlokasi, chketteam, KP
    		   ) AS d 
          INNER JOIN DtCMOBI.CK_Market_GC AS b
	      		  ON d.chtipemarket = LEFT(CAST(b.Tipemarket AS VARCHAR),1) AND d.chketlokasi = Ket_Lokasi
    	  GROUP BY intahun, chketteam, Market_Nielsen, KP
    	 ) AS s
) AS z
GROUP BY 1, 2, 3, 4)
SELECT * FROM EAO_For_GC_1
WHERE KP like '%FULLO%'
ORDER BY  INTAHUN

